lsc('LS-85', 'نظام الإذاعة الداخلية والإخلاء الصوتي',
  'توريد وتركيب واختبار نظام الإذاعة الداخلية والإخلاء الصوتي (Bosch Praesideo/Plena أو DSPPA): الكبينة المركزية والمضخمات والخلاطات بقدرات تغطي جميع المناطق، ووحدة التحكم ومايكروفون النداء في الاستقبال، والسماعات السقفية ومفاتيح التحكم بالصوت، والتقسيم إلى مناطق نداء مستقلة، بكابلات مقاومة للحريق منخفضة الدخان (LSZH)، والربط بإنذار الحريق لرسائل الإخلاء؛ واختبار التغطية ومستوى الصوت لكل منطقة.',
  'كبينة الإذاعة بالمضخمات والخلاطات والمايكروفون (SOW 27.3.1)، والسماعات السقفية (27.3.2). الشاشات الرقمية بند اختياري مستقل.')
new('MATV', '27', 'نظام التلفزة المركزية (MATV)',
  'توريد وتركيب واختبار نظام التلفزة المركزية (MATV) حسب المخططات: الأطباق والهوائيات ووحدة الرأس (Head-End) والمضخمات والموزعات وكابلات التوزيع ومخارج التلفاز في مناطق الانتظار والمواقع المحددة، مع ضبط القنوات المعتمدة واختبار جودة الإشارة عند كل مخرج. تلتزم أي شاشة تُورَّد ضمن هذا النظام بمعيار التجمع للشاشات الرقمية AAHC-FM-STD-DIGITAL-SIGNAGE-001.',
  'نظام MATV (SOW 27.2.1).', ['27 41 33'])
new('CLOCK', '27', 'نظام الساعات المركزية',
  'توريد وتركيب وتشغيل نظام الساعات المركزية: ساعات شبكية (IP) تعمل بتغذية PoE في المواقع المحددة، ووحدة التحكم الرئيسية (Master Clock) المتزامنة مع مصدر وقت قياسي (NTP أو GPS)، والبرمجة والاختبار.',
  'الساعات الشبكية (SOW 27.4.1) ووحدة التحكم (27.4.2).', ['27 53 13'])
new('AV', '27', 'الأنظمة السمعية والمرئية لغرفة الاجتماعات ومركز التدريب',
  'توريد وتركيب وتشغيل الأنظمة السمعية والمرئية لغرفة الاجتماعات ومركز التدريب في الدور الأول: شاشات العرض أو أجهزة الإسقاط والشاشات، ونظام الصوت (الميكروفونات والمعالج والمضخم والسماعات)، ونقاط التوصيل السلكية واللاسلكية على الطاولات، ونظام التحكم الموحد، وتجهيز المؤتمرات المرئية؛ مع تقديم مخطط النظام والعينات للاعتماد قبل التوريد، والتزام الشاشات بمعيار التجمع للشاشات الرقمية.',
  'غرفة الاجتماعات (SOW 27.5.1) ومركز التدريب (27.5.2).', ['27 41 13', '27 41 19', '27 41 23', '27 41 26', '27 41 29'])
