new('QMS', '27', 'نظام إدارة الطوابير (QMS) — بند اختياري',
  'توريد وتركيب وتشغيل نظام إدارة الطوابير: أجهزة إصدار التذاكر، وشاشات العرض الرئيسية وشاشات النوافذ والعيادات، ولوحات الطلب لمقدمي الخدمة، والنداء الصوتي، والخادم والبرمجيات والتقارير، والربط بأنظمة المواعيد المعتمدة لدى التجمع عند الطلب؛ وتلتزم الشاشات بمعيار التجمع للشاشات الرقمية. بند اختياري يُسعَّر منفصلاً ولا يُنفذ إلا بقرار المالك.',
  'اختياري في نطاق العمل (SOW 28.4.1). الكمية صفر: يُسعَّر ولا يدخل المجموع.', ['27 52 33'], opt=True)
new('SIGN', '27', 'الشاشات الرقمية — بند اختياري',
  'توريد وتركيب وتشغيل شاشات العرض الرقمية بالأحجام والمواقع المحددة وفق معيار تجمع الأحساء الصحي للشاشات الرقمية AAHC-FM-STD-DIGITAL-SIGNAGE-001: شاشات عرض تجارية مصممة للتشغيل المتواصل (Samsung QMC أو ما يعادلها المعتمد، وQHC للمناطق عالية الإضاءة) بدقة 4K UHD كحد أدنى، ولا يُقبل التلفزيون المنزلي في المناطق العامة؛ وربط شاشات المناطق العامة بمنصة Navori بمشغّل مدمج أو خارجي؛ ومقبسان كهربائيان خلف كل شاشة (أحدهما على الطوارئ أو UPS حيث أمكن) ونقطة شبكة سلكية RJ45؛ وإخفاء جميع الكابلات؛ والمقاسات وارتفاعات التركيب حسب جداول المعيار. بند اختياري يُسعَّر منفصلاً.',
  'اختياري في نطاق العمل (SOW — Digital signages). الكمية صفر: يُسعَّر ولا يدخل المجموع.', ['27 41 16'], opt=True)
new('XRAYE', '26', 'التجهيزات الكهربائية المسبقة لغرفة الأشعة — بند اختياري',
  'تنفيذ التجهيزات الكهربائية المسبقة لجهاز الأشعة حسب متطلبات الموقع (Site Requirements) الصادرة من مورد الجهاز المعتمد: لوحة التغذية المخصصة بقاطعها وسعتها، ومفتاح الفصل الطارئ، والمجاري والقنوات الأرضية والسقفية للكابلات، ونقاط الشبكة، ومصباح التحذير عند المدخل وربطه بالجهاز؛ بالتنسيق مع قسم التجهيزات الطبية قبل التنفيذ. بند اختياري يُسعَّر منفصلاً.',
  'اختياري في نطاق العمل (SOW 29). الكمية صفر: يُسعَّر ولا يدخل المجموع.', ['11 77 13', '26 05 83'], opt=True)

NOTES_ADD = """

ملاحظات خاصة بمركز فاطمة العفالق:
- هذا الجدول مبني على نطاق العمل (SOW) الصادر في 25 أكتوبر 2026 لمركز فاطمة العفالق للرعاية الصحية الأولية، ومقابَل بنداً بنداً ببنود المرجع الفني للتجمع: المساحة المبنية 2,850 م² (الأرضي 1,780، الأول 1,037، السطح 33)، والمسطحات الخضراء 3,772 م²، ومساحة الأرض 5,552 م².
- مستبعد من هذا الجدول كما في نطاق العمل: التجهيزات الطبية، والمعدات الكهربائية. أما الأثاث غير الطبي فمشمول في هذا الجدول بخلاف نطاق العمل.
- البنود الاختيارية (نظام إدارة الطوابير، الشاشات الرقمية، التجهيزات الكهربائية المسبقة لغرفة الأشعة) كميتها صفر: يُسعّرها المقاول ولا تدخل المجموع إلا بقرار المالك.
- الكميات والسعات تُحسب من المخططات المعتمدة على مسؤولية المقاول، وأي اختلاف بين نطاق العمل والمواصفة يُعتمد فيه الأعلى."""

def sql():
  out = ["-- 0080: جدول كميات «مقطوعية — مركز فاطمة العفالق» من نطاق عمل الشركة القابضة (25-10-2026)، مقابَل ببنود المرجع الفني. المولّد tools/boq/mk80_fatima.py",
         "do $do$ declare src record; prj uuid; nb uuid; begin",
         "  if exists (select 1 from public.seed_marks where key = 'fatima_boq_v1') then return; end if;",
         "  select id into prj from public.projects where name like '%فاطمة العفالق%' order by created_at limit 1;",
         "  if prj is null then return; end if;",
         "  select bq.* into src from public.boqs bq join public.projects p on p.id = bq.project_id where p.name like '%النعيم%' and bq.name = 'مقطوعية — نموذج المسار الرابع' order by bq.created_at limit 1;",
         "  insert into public.boqs (project_id, name, status, contingency, vat, factor, notes, created_by, pricing, hide_prices, handover)",
         f"    values (prj, 'مقطوعية — مركز فاطمة العفالق', 'draft', coalesce(src.contingency, 5), coalesce(src.vat, 15), coalesce(src.factor, 1), coalesce(src.notes, '') || {q(NOTES_ADD)}, src.created_by, 'lumpsum', true, coalesce(src.handover, true)) returning id into nb;"]
  for i, x in enumerate(L):
    s = (i + 1) * 10; qty = '0' if x['mode'] == 'opt' else '1'; note = q(x['note']) if x['note'] else 'null'
    if x['mode'] == 'copy':
      out.append(f"  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, {note}, {s}, 'free', title, descr, coalesce(nullif(unit, ''), 'مقطوعية'), div_code, code, refs from public.ls_items where code = {q(x['ls'])};")
    elif x['mode'] == 'ls':
      out.append(f"  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, {note}, {s}, 'free', {q(x['title'])}, {q(x['descr'])}, 'مقطوعية', div_code, code, coalesce(refs, '{{}}') || {arr(x['refs'])} from public.ls_items where code = {q(x['ls'])};")
    else:
      out.append(f"  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) values (nb, {qty}, {note}, {s}, 'free', {q(x['title'])}, {q(x['descr'])}, 'مقطوعية', {q(x['div'])}, null, {arr(x['refs'])});")
  out += ["  insert into public.seed_marks (key) values ('fatima_boq_v1');", "end $do$;", ""]
  return '\n'.join(out)

if __name__ == '__main__':
  open(os.path.join(ROOT, 'supabase', 'migrations', '0080_fatima_boq.sql'), 'w').write(sql())
  json.dump(L, open(os.path.join(os.path.dirname(__file__), 'fatima_lines.json'), 'w'), ensure_ascii=False, indent=0)
  print(len(L), 'lines')
